        handler = DataHandler("source")
        handler.data = {"a": 1, "b": 2}
        result = handler.transform(lambda x: x * 2)
        assert result == {"a": 2, "b": 4}

    def test_transform_empty_dict(self):
        """边界用例：空数据字典"""
        handler = DataHandler("source")
        handler.data = {}
        result = handler.transform(lambda x: x)
        assert result == {}

